(()=>{const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'calculate_ipv4_subnet',title:'Calculate IPv4 subnet',description:'Set the visible IPv4 calculator inputs and calculate network, address range and usable hosts.',inputSchema:{type:'object',properties:{ip:{type:'string'},prefix:{type:'integer',minimum:0,maximum:32}},required:['ip','prefix'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.ip!=='string'||!Number.isInteger(input.prefix)||Object.keys(input).some(k=>!['ip','prefix'].includes(k)))throw Error('Expected only ip (string) and prefix (integer).');const result=Net.subnet(input.ip,input.prefix);navigate('ipv4');document.getElementById('ip').value=input.ip;document.getElementById('pfx').value='/'+input.prefix;document.getElementById('calculate').click();return{network:result.cidr,mask:result.mask,broadcast:result.broadcast,firstHost:result.first,lastHost:result.last,usableHosts:result.hosts};}},{signal:life.signal})).catch(()=>{});}catch{}})();
